import { keyframes } from '@emotion/react';

export const rotate = keyframes`
from {
  transform: rotate(0deg);
}
to {
  transform: rotate(360deg);
}
`;

export const colorCycle = keyframes`
  0%   { background-color: rgb(129, 75, 255); }  /* --as-purple */
  10%  { background-color: rgb(39, 39, 39); }     /* --as-dark-grey */
  20%  { background-color: rgb(82, 81, 81); }     /* --as-light-grey */
  30%  { background-color: rgb(255, 89, 89); }    /* --as-red */
  40%  { background-color: #0084f5; }              /* --as-blue */
  50%  { background-color: #35fcff; }              /* --as-light-blue */
  60%  { background-color: #26e290; }              /* --frontend */
  70%  { background-color: #1ac8ed; }              /* --creative */
  80%  { background-color: #d2c1ff; }              /* --other */
  90%  { background-color: #08090a; }              /* --aiml */
  100% { background-color: rgb(129, 75, 255); }   /* --as-purple */
`;
